    let count = 0;
    const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

    const dfs = (r, c) => {
        const stack = [];
        grid[r][c] = "0";
        stack.push([r, c]);

        while (stack.length) {
            [r, c] = stack.pop();
            for (const [dr, dc] of directions) {
                const nr = r + dr;
                const nc = c + dc;
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] === "1") {
                    grid[nr][nc] = "0";
                    stack.push([nr, nc]);
                }
            }
        }
    };

    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (grid[r][c] === "1") {
                count++;
                dfs(r, c);
            }
        }
    }

    return count;
};
